 1→import { useState, useEffect, useCallback } from 'react';
 2→import { useTranslation } from '../hooks/useTranslation';
 3→import { fetchMemories, deleteMemory as apiDeleteMemory } from '../services/memoriesService';
 4→import type { MemoryEntry } from '../services/memoriesService';
 5→import './MemoriesPanel.css';
 6→
 7→interface MemoriesPanelProps {
 8→  refreshKey: number;
 9→}
10→
11→const CATEGORY_ORDER: MemoryEntry['category'][] = ['preference', 'fact', 'pattern'];
12→
13→const CATEGORY_I18N: Record<MemoryEntry['category'], string> = {
14→  preference: 'preferencesCategory',
15→  fact: 'factsCategory',
16→  pattern: 'patternsCategory',
17→};
18→
19→const CATEGORY_EMPTY_I18N: Record<MemoryEntry['category'], string> = {
20→  preference: 'noPreferences',
21→  fact: 'noFacts',
22→  pattern: 'noPatterns',
23→};
24→
25→export function MemoriesPanel({ refreshKey }: MemoriesPanelProps) {
26→  const { t } = useTranslation();
27→  const [entries, setEntries] = useState<MemoryEntry[]>([]);
28→
29→  const loadMemories = useCallback(async () => {
30→    try {
31→      const data = await fetchMemories();
32→      setEntries(data.entries);
33→    } catch {
34→      // silently ignore
35→    }
36→  }, []);
37→
38→  useEffect(() => { loadMemories(); }, [loadMemories, refreshKey]);
39→
40→  useEffect(() => {
41→    const handler = () => loadMemories();
42→    window.addEventListener('memories-updated', handler);
43→    return () => window.removeEventListener('memories-updated', handler);
44→  }, [loadMemories]);
45→
46→  const handleDelete = async (content: string) => {
47→    if (!confirm(t('deleteMemoryConfirm'))) return;
48→    try {
49→      await apiDeleteMemory(content);
50→      await loadMemories();
51→    } catch {
52→      // silently ignore
53→    }
54→  };
55→
56→  const grouped = CATEGORY_ORDER
57→    .map((cat) => ({ category: cat, items: entries.filter((e) => e.category === cat) }));
58→
59→  return (
60→    <div className="memories-panel">
61→      {grouped.map((group) => (
62→        <div key={group.category} className="memories-panel__section">
63→          <h3 className="memories-panel__section-title">{t(CATEGORY_I18N[group.category])}</h3>
64→          {group.items.length === 0 ? (
65→            <p className="memories-panel__section-empty">{t(CATEGORY_EMPTY_I18N[group.category])}</p>
66→          ) : (
67→            <ul className="memories-panel__list">
68→              {group.items.map((entry, idx) => (
69→                <li key={`${group.category}-${idx}`} className="memories-panel__item">
70→                  <span className="memories-panel__text">{entry.content}</span>
71→                  <button
72→                    className="memories-panel__delete-btn"
73→                    onClick={() => handleDelete(entry.content)}
74→                    title={t('deleteMemory')}
75→                  >
76→                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
77→                  </button>
78→                </li>
79→              ))}
80→            </ul>
81→          )}
82→        </div>
83→      ))}
84→    </div>
85→  );
86→}
