73→}
74→
75→export interface ChatMessage {
76→  id: string;
77→  role: 'user' | 'assistant';
78→  content: string;
79→  toolCalls?: ToolCallResult[];
80→  segments?: ContentSegment[];
81→  isStreaming?: boolean;
82→  currentPhase?: 'thinking' | 'answer';
83→}
