export interface MemoryEntry {
  category: 'preference' | 'fact' | 'pattern';
  content: string;
}

export interface MemoriesResponse {
  entries: MemoryEntry[];
  raw: string;
}

export async function fetchMemories(): Promise<MemoriesResponse> {
  const resp = await fetch('/api/memories');
  if (!resp.ok) throw new Error('Failed to fetch memories');
  return resp.json();
}

export async function deleteMemory(content: string): Promise<void> {
  const resp = await fetch('/api/memories', {
    method: 'DELETE',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ content }),
  });
  if (!resp.ok) {
    const err = await resp.json();
    throw new Error(err.error || 'Failed to delete memory');
  }
}

from fastapi import APIRouter
from fastapi.responses import JSONResponse
from pydantic import BaseModel

from app.agent_memory import read_memories, forget_memory

router = APIRouter(prefix="/api", tags=["memories"])


class DeleteMemoryRequest(BaseModel):
    content: str


@router.get("/memories")
async def api_list_memories():
    raw = read_memories(user_id="default")
    entries = []
    current_category = "fact"
    category_map = {
        "## Preferences": "preference",
        "## Facts": "fact",
        "## Patterns": "pattern",
    }
    for line in raw.split("\n"):
        stripped = line.strip()
        if stripped in category_map:
            current_category = category_map[stripped]
        elif stripped.startswith("- "):
            entries.append({
                "category": current_category,
                "content": stripped[2:],
            })
    return {"entries": entries, "raw": raw}


@router.delete("/memories")
async def api_delete_memory(request: DeleteMemoryRequest):
    result = forget_memory(request.content, user_id="default")
    if result != "Memory forgotten.":
        return JSONResponse(status_code=404, content={"error": result})
    return {"status": "deleted"}

import os
import threading

from app.config import MEMORIES_DIR

_lock = threading.Lock()


def _memory_path(user_id: str = "default") -> str:
    user_dir = os.path.join(MEMORIES_DIR, user_id)
    os.makedirs(user_dir, exist_ok=True)
    return os.path.join(user_dir, "MEMORY.md")


_SKELETON = "# Agent Memory\n\n## Preferences\n\n## Facts\n\n## Patterns\n"


def read_memories(user_id: str = "default") -> str:
    path = _memory_path(user_id)
    with _lock:
        if not os.path.exists(path):
            return ""
        with open(path, "r") as f:
            return f.read()


def save_memory(content: str, category: str = "fact", user_id: str = "default") -> str:
    valid_categories = {"preference", "fact", "pattern"}
    if category not in valid_categories:
        category = "fact"

    section_headers = {
        "preference": "## Preferences",
        "fact": "## Facts",
        "pattern": "## Patterns",
    }
    section_header = section_headers[category]
    entry = f"- {content}"

    path = _memory_path(user_id)
    with _lock:
        if os.path.exists(path):
            with open(path, "r") as f:
                text = f.read()
        else:
            text = _SKELETON

        # Exact line-level duplicate check
        existing_lines = text.split("\n")
        if entry in existing_lines:
            return "Memory already exists."

        # Find section and append
        if section_header in text:
            section_start = text.index(section_header) + len(section_header)
            next_section = text.find("\n## ", section_start)
            if next_section == -1:
                text = text.rstrip() + f"\n{entry}\n"
            else:
                text = text[:next_section].rstrip() + f"\n{entry}\n" + text[next_section:]
        else:
            text = text.rstrip() + f"\n\n{section_header}\n{entry}\n"

        with open(path, "w") as f:
            f.write(text)
    return "Memory saved."


def forget_memory(content: str, user_id: str = "default") -> str:
    path = _memory_path(user_id)
    entry = f"- {content}"

    with _lock:
        if not os.path.exists(path):
            return "No memories found."
        with open(path, "r") as f:
            lines = f.readlines()

        found = False
        new_lines = []
        for line in lines:
            if line.rstrip("\n") == entry and not found:
                found = True
                continue
            new_lines.append(line)

        if not found:
            return "Memory not found."

        with open(path, "w") as f:
            f.writelines(new_lines)
    return "Memory forgotten."

